import {readTemplate,fillTemplate} from './template-bridge.mjs?v=launch-1.0';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let api={},loaded=null,owner='',filename='',mapping={},busy=false;
export function initTemplate(options){api=options;}
export function templateBridge(){if(owner!==api.project().id){loaded=null;mapping={};owner=api.project().id;}return `<div class="prep-section-title"><span>OFFICIAL TEMPLATE / TEXT ONLY</span><h3>The organizer’s canvas.<br><em>Your own words.</em></h3><p>Upload a PPTX and choose which text boxes receive your content. The bridge keeps the original slides, masters, themes, and media. Recognized title and footer placeholders are locked.</p></div><div class="notice neutral">This is a text replacement tool. It does not render or certify the final layout. Text length, fonts, special shapes, and organizer restrictions still need a manual check in PowerPoint. Use the original file when the template cannot be safely adapted.</div><div class="panel"><label for="official-pptx"><strong>Choose the organizer’s PPTX</strong></label><input id="official-pptx" type="file" accept=".pptx,application/vnd.openxmlformats-officedocument.presentationml.presentation" ${busy?'disabled':''}><p class="hint">Up to 8 MB and 40 slides. Processed in this browser, kept in memory for this project until you switch projects or close the tab. Re-upload after reopening. Macros, encrypted files, and embedded objects are rejected.</p><p role="status" id="template-status">${busy?'Reading template…':loaded?esc(filename)+' · '+loaded.slides+' slides · '+loaded.slots.length+' text boxes':'No template loaded.'}</p></div>${loaded?`<section class="template-slot-list">${loaded.slots.map(s=>`<article class="template-slot"><div><span class="eyebrow">SLIDE ${s.slide} / ${esc(s.label)}</span><p>${esc(s.text||'(Empty text box)')}</p></div><div><label for="slot-${esc(s.id)}">${s.locked?'Protected placeholder':'Replace with'}</label><select id="slot-${esc(s.id)}" data-template-slot="${esc(s.id)}" ${s.locked?'disabled':''}><option value="">Keep original text</option>${['name','team','problem','solution','approach','proof','impact','ask'].map(k=>`<option value="${k}" ${mapping[s.id]===k?'selected':''}>${k[0].toUpperCase()+k.slice(1)}</option>`).join('')}</select></div></article>`).join('')}</section><div class="template-export-bar"><p>Unmapped boxes keep their original text. Replacements use the first text run’s formatting; review overflow and mixed formatting in PowerPoint.</p><button class="btn primary" data-fill-template ${busy?'disabled':''}>Download filled template ↓</button></div>`:''}`;}
document.addEventListener('change',async e=>{if(e.target.dataset.templateSlot){mapping[e.target.dataset.templateSlot]=e.target.value;return;}if(e.target.id!=='official-pptx'||!e.target.files[0])return;const file=e.target.files[0],projectId=api.project().id;if(!/\.pptx$/i.test(file.name))return api.toast('Choose a .pptx file.');if(file.size>8*1024*1024)return api.toast('Use a file smaller than 8 MB.');busy=true;loaded=null;mapping={};api.render();try{await api.loadScript('/vendor/jszip.min.js');const result=await readTemplate(new Uint8Array(await file.arrayBuffer()),window.JSZip);if(api.project()?.id!==projectId)return;loaded=result;filename=file.name;owner=projectId;api.toast('Template loaded. Choose the text boxes to fill.');}catch(error){api.toast(error.message);}finally{busy=false;api.render();}});
document.addEventListener('click',async e=>{if(!e.target.closest('[data-fill-template]')||!loaded||busy)return;busy=true;api.render();try{const result=await fillTemplate(loaded,mapping,api.project());api.download(result.blob,filename.replace(/\.pptx$/i,'')+'-filled-draft.pptx');api.toast(result.changed+' text boxes filled. Open the file and check the layout.');}catch(error){api.toast(error.message);}finally{busy=false;api.render();}});
